        UNION { VALUES ?root { wd:Q1563053 wd:Q131464966 wd:Q829546 wd:Q386027 wd:Q125389947 wd:Q1142922 wd:Q76761438 wd:Q2112188 wd:Q188267 wd:Q2257608 wd:Q1623338 wd:Q3359858 wd:Q27924245 wd:Q133821883 wd:Q2623817 wd:Q124153669 wd:Q1063293 wd:Q140313137 wd:Q7291990 wd:Q583461 } ?item wdt:P279 ?root }
        UNION { VALUES ?root { wd:Q1563053 wd:Q131464966 wd:Q829546 wd:Q386027 wd:Q125389947 wd:Q1142922 wd:Q76761438 wd:Q2112188 wd:Q188267 wd:Q2257608 wd:Q1623338 wd:Q3359858 wd:Q27924245 wd:Q133821883 wd:Q2623817 wd:Q124153669 wd:Q1063293 wd:Q140313137 wd:Q7291990 wd:Q583461 } BIND(?root AS ?item) }
